/// Opens the canonical manifests that `resolve_packages` is about to open one at a time, on several threads: opening
/// reads and parses the file, which is independent per manifest. One that fails to open is opened again below, which
/// reports it.
fn prewarm_manifests(
    package_manifest_decls: &BTreeMap<PackageId, (PathBuf, Vec<ManifestDecl>)>,
    manifest_cache: &RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>,
    ctx: &OpenContext<'_>,
) {
    let wanted: Vec<&ManifestDecl> = package_manifest_decls
        .values()
        .flat_map(|(_, decls)| decls.iter())
        .filter(|decl| decl.role == ManifestRole::Canonical && !manifest_cache.borrow().contains_key(&decl.path))
        .collect();
    let opened = map_in_parallel(&wanted, |decl| callisto_manifests::open(decl, ctx));
    let mut cache = manifest_cache.borrow_mut();
    for (decl, opened) in wanted.into_iter().zip(opened) {
        if let Ok(manifest) = opened {
            cache.insert(decl.path.clone(), Arc::from(manifest));
        }
    }
}

/// Applies `[[package]]` rules, exact and glob, to each identified package, then reports rules that matched
/// nothing or matched across ecosystems.
fn resolve_packages(
    package_manifest_decls: BTreeMap<PackageId, (PathBuf, Vec<ManifestDecl>)>,
    index: &IdentityIndex,
    cfg: &ResolvedConfig,
    manifest_cache: &RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>,
    ctx: &OpenContext<'_>,
    diagnostics: &mut Vec<Diagnostic>,
) -> Result<BTreeMap<PackageId, Package>, GraphError> {
    prewarm_manifests(&package_manifest_decls, manifest_cache, ctx);

    // A rule that matches no package is usually a typo, so track which rules matched.
    let mut package_rule_matched = vec![false; cfg.packages.len()];
    let mut package_rule_hint: Vec<Option<String>> = vec![None; cfg.packages.len()];

    let mut packages = BTreeMap::new();
    for (id, (rel_path, decls)) in package_manifest_decls {
        let ch_path = rel_path.join("CHANGELOG.md");
        let mut publish_to = Vec::new();
        // Attached platform manifests publish as their owner's platform operations, not as targets.
        for decl in decls.iter().filter(|d| d.role == ManifestRole::Canonical) {
            match open_cached(manifest_cache, decl, ctx) {
                Ok(editor) => {
                    for target in editor.publish_targets() {
                        if target != PublishTarget::None && !publish_to.contains(&target) {
                            publish_to.push(target);
                        }
                    }
                }
                Err(error) => diagnostics.push(unresolved(
                    &decl.path,
                    "open its manifest to read its publish targets",
                    error,
                )),
            }
        }
        if publish_to.is_empty() {
            publish_to.push(PublishTarget::None);
        }

        // The ecosystems this package's manifests were found in.
        let package_ecosystems: Vec<Ecosystem> = decls.iter().map(|d| d.ecosystem()).collect();

        // The exact [[package]] rule, else the first glob rule, that configures this package.
        let native_names: Vec<(Ecosystem, &str)> = index.native_names(&id).collect();
        let active_override = resolve_package_config(&native_names, cfg);

        // Record every matching rule, even a shadowed one, for the zero-match diagnostic.
        for (idx, (rule, _)) in cfg.packages.iter().enumerate() {
            if rule.applies(&native_names) {
                package_rule_matched[idx] = true;
            } else if let PackageMatch::Exact(rule_id) = rule
                && package_rule_hint[idx].is_none()
            {
                package_rule_hint[idx] = index.suggest_native(&rule_id.to_string());
            }
        }

        // Single source of truth for the default: ReleaseTrigger's #[default].
        let release_trigger = active_override.and_then(|o| o.release_trigger).unwrap_or_default();

        let tag_template = active_override.and_then(|o| o.tag_template.clone());

        let changelog = if let Some(override_path) = active_override.and_then(|o| o.changelog.as_ref()) {
            Some(rel_path.join(override_path))
        } else {
            Some(ch_path)
        };

        // Reject a configured publish target whose ecosystem matches none of the package's detected ones; only here are the real manifests known.
        if let Some(override_targets) = active_override.and_then(|o| o.publish_to.as_deref()) {
            for target in override_targets {
                if let Some(target_ecosystem) = target.ecosystem()
                    && !package_ecosystems.contains(&target_ecosystem)
                {
                    return Err(GraphError::PublishTargetEcosystemMismatch {
                        package: id.clone(),
                        target: target.config_str().to_string(),
                        target_ecosystem,
                        package_ecosystems,
                    });
                }
            }
            // The override picks which targets publish; manifest-derived fields it leaves unset (npm access/registry) are kept.
            publish_to = override_targets
                .iter()
                .map(|target| {
                    let manifest_target = target
                        .ecosystem()
                        .and_then(|eco| publish_to.iter().find(|m| m.ecosystem() == Some(eco)));
                    match manifest_target {
                        Some(manifest_target) => target.clone().merge_manifest_gaps(manifest_target),
                        None => target.clone(),
                    }
                })
                .collect();
        }

        let pkg = Package {
            id: id.clone(),
            manifests: decls,
            changelog,
            release_trigger,
            publish_to,
            tag_template,
        };
        packages.insert(id, pkg);
    }

    // Advisory, not an error: a monorepo-wide rule can match nothing on a partial checkout.
    for (idx, (rule, _)) in cfg.packages.iter().enumerate() {
        if !package_rule_matched[idx] {
            diagnostics.push(Diagnostic {
                code: DiagnosticCode::PackageRuleMatchedNothing,
                severity: DiagnosticSeverity::Warning,
                message: match &package_rule_hint[idx] {
